      text-align: center;
      line-height: 40px;
      font-size: 20px;
    }
    .tooltip {
      background: #333;
      color: white;
      padding: 4px 8px;
      z-index: 100;
    }
    .banner {
      position: relative;
      z-index: 10;
      background: tomato;
      color: white;
      padding: 8px;
      margin-top: -10px;
    }
  &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;h1&gt;Show a tooltip above an icon&lt;/h1&gt;
  &lt;p&gt;The dark tooltip should appear in front of the red banner. Does it?&lt;/p&gt;
