  &lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
  &lt;title&gt;Make a Full-Width Header&lt;/title&gt;
  &lt;style&gt;
    body {
      margin: 0;
    }
    .header {
      width: 100vw;
      background: steelblue;
      color: white;
      padding: 16px;
      box-sizing: border-box;
    }
    .content {
      height: 200vh; /* tall enough to force a vertical scrollbar */
      padding: 16px;
    }
  &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;div class="header"&gt;Full-width header&lt;/div&gt;
  &lt;div class="content"&gt;
    &lt;h1&gt;Make a full-width header&lt;/h1&gt;
